import json,subprocess
probe="""import os,json,urllib.request,urllib.error
k=os.environ.get('AI_CORE_API_KEY','')
out={'configured':len(k)>=16,'gate_models':{}}
for name,port in [('granite',18181),('qwen3',18182),('ministral',18183),('coder',18184)]:
 try:
  r=urllib.request.Request('http://127.0.0.1:'+str(port)+'/v1/models',headers={'Authorization':'Bearer '+k})
  with urllib.request.urlopen(r,timeout=5) as f:
   data=json.load(f)
   out['gate_models'][name]={'status':f.status,'count':len(data.get('data',[]))}
 except urllib.error.HTTPError as e:out['gate_models'][name]={'status':e.code}
 except Exception as e:out['gate_models'][name]={'error':type(e).__name__}
print(json.dumps(out))
"""
p=subprocess.run(['docker','exec','ai-core-model-gate','python3','-c',probe],text=True,capture_output=True,timeout=40)
