body='AI_CORE_GATE_SELF_AUTH_SMOKE\n'+json.dumps(result,ensure_ascii=False,indent=2)
r=subprocess.run(['gh','api','-X','POST','repos/G-ACE-inc/server-core/issues/10/comments','--input','-','--jq','.html_url'],input=json.dumps({'body':body}),text=True,capture_output=True,timeout=20)
print('GATE_SELF_AUTH_REPORT='+('PASS '+r.stdout.strip() if r.returncode==0 else 'FAILED'))
